use super::*;
use photocraft_engine::doc::{AlphaChannel, ColorMode, LayerId, LayerMask, PixelFormat, Rect, SampleType, Slice, SliceOrigin};
use std::{io::Read, path::PathBuf, sync::atomic::{AtomicBool,Ordering}};

struct Directory(PathBuf);
impl Drop for Directory{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn directory()->Directory{let path=std::env::temp_dir().join(format!("place-input-{}",ulid::Ulid::new()));std::fs::create_dir_all(&path).unwrap();Directory(path)}
fn rgba()->Vec<u8>{vec![255,0,0,255,0,255,0,255,0,0,255,255,255,255,255,255]}
fn png(width:u32,height:u32,bytes:Vec<u8>)->Vec<u8>{let image=photocraft_codecs::Image::from_u8(width,height,photocraft_codecs::ChannelLayout::Rgba,bytes).unwrap();photocraft_codecs::encode(&image,photocraft_codecs::Format::Png,&Default::default()).unwrap()}
fn encoded(format:&str)->Vec<u8>{match format{"png"=>png(2,2,rgba()),"psd"|"psb"=>{use photocraft_psd::{Compression,LayerSpec,PixelData,PsdBuilder,Version};let mut builder=PsdBuilder::new(2,2).version(if format=="psb"{Version::Psb}else{Version::Psd}).compression(Compression::Raw);builder.push_layer(LayerSpec::new("Known",0,0,2,2,PixelData::Rgba8(rgba())));builder.composite(PixelData::Rgba8(rgba()));builder.to_bytes().unwrap()},"pcraft"=>photocraft_engine::smart_cmds::encode_source(&photocraft_io::import("source.png",&png(2,2,rgba())).unwrap().document).unwrap(),_=>unreachable!()}}
struct Fixture{directory:Directory,engine:Session,id:LayerId,group:LayerId,nested:LayerId,path:PathBuf,bytes:Vec<u8>}
fn fixture(depth:u32,format:&str)->Fixture{let directory=directory();let path=directory.0.join(format!("placed.image.{format}"));let bytes=encoded(format);std::fs::write(&path,&bytes).unwrap();let mut engine=Session::new();engine.execute("file.new",json!({"width":12,"height":10,"depth":depth})).unwrap();let fmt=engine.active().unwrap().doc.pixel_format();let mut first=Layer::raster("Original",fmt);first.surface_mut().unwrap().fill_rect(Rect::from_xywh(1,1,1,1),&[0.2,0.4,0.6,1.]);first.mask=Some(LayerMask::reveal_all());let nested=Layer::raster("Nested",fmt);let ids=[first.id,nested.id];let group=Layer::group("Group",vec![nested]);let group_id=group.id;engine.edit("Placement fixture",|doc,current|{doc.layers=vec![first,group];*current=Some(ids[0]);let mut coverage=photocraft_raster::Surface::new(PixelFormat::GRAY8);coverage.fill_rect(Rect::from_xywh(3,2,2,3),&[0.5]);doc.selection=Some(coverage.clone());doc.channels.push(AlphaChannel::new("Retained alpha",coverage.clone()));doc.quick_mask=Some(AlphaChannel::new("Quick Mask",coverage));doc.metadata.psd_global_blocks.push((*b"8BIM",*b"zzzz",Arc::new(b"retained global".to_vec())));doc.slices.list=vec![Slice{id:1,origin:SliceOrigin::Layer,layer:Some(ids[0]),rect:Rect::from_xywh(1,1,1,1),..Default::default()}];Ok(())}).unwrap();let index=engine.active_index().unwrap();engine.execute("document.activate",json!({"document":index})).unwrap();let state=engine.active_mut().unwrap();state.selected_layers=vec![ids[0],ids[1]];state.layer_anchor=Some(ids[1]);state.channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Alpha(0);engine.tools.foreground=[0.2,0.3,0.4,0.5];engine.tools.background=[0.7,0.6,0.5,0.4];let state=engine.active().unwrap();engine.edit_state.fade=Some(photocraft_engine::edit_menu_cmds::FadeSource{doc:state.doc.id,revision:state.revision,layer:ids[0],mask:false,label:"Older placement Fade".into()});Fixture{directory,engine,id:ids[0],group:group_id,nested:ids[1],path,bytes}}
fn twin(engine:&Session)->Session{let state=engine.active().unwrap();let mut copy=Session::new();copy.add_document(Document::new("Twin",state.doc.size,state.doc.mode,state.doc.depth),None);*copy.active_mut().unwrap()=state.clone();copy.journal=engine.journal.clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.clipboard=engine.clipboard.clone();copy.style_clipboard=engine.style_clipboard.clone();copy.edit_state=engine.edit_state.clone();super::super::color_views::Snapshot::capture(engine).unwrap().install(&mut copy).unwrap();copy}
fn mapped(id:LayerId,pairs:&[(LayerId,LayerId)])->LayerId{pairs.iter().find(|(native,_)|*native==id).map_or(id,|(_,actual)|*actual)}
fn normalized(doc:&Document,pairs:&[(LayerId,LayerId)])->Document{let mut doc=doc.clone();for(native,actual)in pairs{if let Some(layer)=doc.layer_mut(*native){layer.id=*actual;}}for slice in &mut doc.slices.list{slice.layer=slice.layer.map(|id|mapped(id,pairs));}doc}
fn same(actual:&Session,native:&Session,pairs:&[(LayerId,LayerId)]){let a=actual.active().unwrap();let n=native.active().unwrap();assert_eq!(*a.doc,normalized(&n.doc,pairs));assert_eq!(a.history.entries(),n.history.entries());assert_eq!(a.history.past_len(),n.history.past_len());for index in 0..a.history.past_len(){assert_eq!(*a.history.state(index).unwrap(),normalized(&n.history.state(index).unwrap(),pairs));}assert_eq!(a.history.redo_labels().collect::<Vec<_>>(),n.history.redo_labels().collect::<Vec<_>>());assert_eq!((a.revision,a.saved_revision,&a.coalesce,&a.path,&a.last_damage),(n.revision,n.saved_revision,&n.coalesce,&n.path,&n.last_damage));assert_eq!(a.active_layer,n.active_layer.map(|id|mapped(id,pairs)));assert_eq!(a.selected_layers,n.selected_layers.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(a.layer_anchor,n.layer_anchor.map(|id|mapped(id,pairs)));assert_eq!(a.channel_view,n.channel_view);assert_eq!(a.isolated_layers,n.isolated_layers.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(a.fx_collapsed,n.fx_collapsed.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(format!("{:?}",a.symmetry_path),format!("{:?}",n.symmetry_path));assert_eq!(actual.journal,native.journal);assert_eq!(actual.edit_state.fade,native.edit_state.fade);assert_eq!(actual.tools.foreground,native.tools.foreground);assert_eq!(actual.tools.background,native.tools.background);assert_eq!(actual.tools.brush,native.tools.brush);assert_eq!(actual.style_clipboard,native.style_clipboard);assert_eq!(format!("{:?}",actual.clipboard),format!("{:?}",native.clipboard));assert_eq!(super::super::tools::presets(actual),super::super::tools::presets(native));assert_eq!(super::super::color_views::key(actual).unwrap(),super::super::color_views::key(native).unwrap());}
fn unchanged(engine:&Session,before:&Session){same(engine,before,&[]);assert!(Arc::ptr_eq(&engine.active().unwrap().doc,&before.active().unwrap().doc));}
fn host(engine:&mut Session,command:&str,params:Value)->Result<Value,String>{super::super::execute_view_command(engine,command,params)}
fn params(f:&Fixture)->Value{json!({"path":f.path.to_string_lossy(),"vendor":[null,5]})}
fn differential(engine:&mut Session,native:&mut Session,command:&str,params:Value,pairs:&mut Vec<(LayerId,LayerId)>)->(LayerId,Value){let actual=host(engine,command,params.clone()).unwrap();let expected=native.execute(command,params).unwrap();let id=LayerId(actual["layer"].as_u64().unwrap());let native_id=LayerId(expected["layer"].as_u64().unwrap());assert_ne!(id,native_id);let mut expected=expected;expected["layer"]=json!(id.0);assert_eq!(actual,expected);pairs.push((native_id,id));same(engine,native,pairs);(id,actual)}
fn smart(engine:&Session,id:LayerId)->&SmartObject{let LayerContent::Smart(object)=&engine.active().unwrap().doc.layer(id).unwrap().content else{panic!("Not a Smart Object")};object}
fn pixels(engine:&Session,id:LayerId,rect:Rect,raw:&[u8]){let doc=&engine.active().unwrap().doc;let cache=smart(engine,id).cache.as_ref().unwrap();let tolerance=match doc.depth{SampleType::U8=>1./255.,SampleType::U16=>2./65535.,SampleType::F32=>1e-6};for y in rect.y0.min(0)-2..rect.y1.max(10)+2{for x in rect.x0.min(0)-2..rect.x1.max(12)+2{let expected=if x>=rect.x0&&x<rect.x1&&y>=rect.y0&&y<rect.y1{let at=((y-rect.y0)*rect.width()as i32+x-rect.x0)as usize*4;[raw[at]as f32/255.,raw[at+1]as f32/255.,raw[at+2]as f32/255.,raw[at+3]as f32/255.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=tolerance,"{:?}/{x},{y}/{channel}:{} != {}",doc.depth,actual[channel],expected[channel]);}assert_eq!(actual[3],expected[3]);}}}
fn enlarged_red(engine:&Session,id:LayerId,x0:i32,y0:i32){
    // Keys a=-1/2 at quarter-pixel centres gives one-axis coverage [51/64,35/32,35/32,51/64].
    let coverage:[f64;4]=[51./64.,35./32.,35./32.,51./64.];let cache=smart(engine,id).cache.as_ref().unwrap();assert_eq!(engine.active().unwrap().doc.depth,SampleType::U16);
    for y in -2..14{for x in -2..16{let expected=if(x0..x0+4).contains(&x)&&(y0..y0+4).contains(&y){let alpha=(coverage[(x-x0)as usize]*coverage[(y-y0)as usize]).min(1.0_f64);[1.,0.,0.,(alpha*65535.).round()as f32/65535.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=2./65535.,"enlarged {x},{y}/{channel}:{} != {}",actual[channel],expected[channel]);}assert_eq!(actual[3],expected[3]);}}
}
fn solid_bounds_and_interior(engine:&Session,id:LayerId,rect:Rect,color:[f32;4]){let cache=smart(engine,id).cache.as_ref().unwrap();assert_eq!(cache.content_bounds(),rect);let center=((rect.x0+rect.x1)/2,(rect.y0+rect.y1)/2);assert_eq!(cache.pixel(center.0,center.1),color);for(x,y)in[(rect.x0-1,center.1),(rect.x1,center.1),(center.0,rect.y0-1),(center.0,rect.y1)]{assert_eq!(cache.pixel(x,y),[0.;4]);}}
fn assert_source(engine:&Session,id:LayerId,command:&str,path:&Path,bytes:&[u8]){let layer=engine.active().unwrap().doc.layer(id).unwrap();assert_eq!(layer.name,"placed.image");let object=smart(engine,id);if command==LINKED{assert_eq!(object.source,SmartSource::Linked{path:path.to_string_lossy().into()});}else{let SmartSource::Embedded{file_name,bytes:actual}=&object.source else{panic!("Not embedded")};assert_eq!(file_name,path.file_name().unwrap().to_str().unwrap());assert_eq!(actual.as_slice(),bytes);}assert!(object.smart_filters.is_empty());assert!(object.psd_raw.is_none());assert!(layer.psd_blocks.is_empty());}

#[test]
fn place_input_both_commands_four_formats_three_depths_native_state_and_independent_literal_pixels(){
    for command in [EMBEDDED,LINKED]{for depth in [8,16,32]{for format in ["png","psd","psb","pcraft"]{let mut f=fixture(depth,format);let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let mut pairs=Vec::new();let request=params(&f);let(id,result)=differential(&mut f.engine,&mut native,command,request,&mut pairs);assert_eq!(result,json!({"layer":id.0,"scale":100.,"bounds":[5.,4.,7.,6.]}));assert_eq!(smart(&f.engine,id).transform,Affine{m:[1.,0.,0.,1.,5.,4.]});assert_source(&f.engine,id,command,&f.path,&f.bytes);pixels(&f.engine,id,Rect::new(5,4,7,6),&rgba());let after=f.engine.active().unwrap().doc.clone();assert_eq!(after.layer(f.id),before.layer(f.id));assert_eq!(after.layer(f.group),before.layer(f.group));assert_eq!(after.metadata,before.metadata);assert_eq!(after.selection,before.selection);assert_eq!(after.channels,before.channels);assert_eq!(after.quick_mask,before.quick_mask);assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);assert_eq!(std::fs::read(&f.path).unwrap(),f.bytes);f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert_eq!(f.engine.active().unwrap().doc,after);}}}
}

#[test]
fn place_input_scale_fit_center_tiny_zero_negative_and_override_follow_native_geometry(){
    for command in [EMBEDDED,LINKED]{for (settings,expected) in [(json!({}),(1.,5.,4.)),(json!({"center":[2,3]}),(1.,1.,2.)),(json!({"center":["fallback",null]}),(1.,5.,4.)),(json!({"scale":200,"center":[4,4]}),(2.,2.,2.)),(json!({"scale":1}),(0.01,6.,5.)),(json!({"scale":0}),(0.0001,6.,5.)),(json!({"scale":-5}),(0.0001,6.,5.)),(json!({"scale":0.000001}),(0.0001,6.,5.)),(json!({"scale":"invalid","center":[1]}),(1.,5.,4.))]{let mut f=fixture(16,"png");f.bytes=png(2,2,[255,0,0,255].repeat(4));std::fs::write(&f.path,&f.bytes).unwrap();let mut request=params(&f);request.as_object_mut().unwrap().extend(settings.as_object().unwrap().clone());assert_eq!(geometry((12,10),(2,2),&request).unwrap(),expected);if expected.0==0.0001{let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let result=host(&mut f.engine,command,request).unwrap();let id=LayerId(result["layer"].as_u64().unwrap());assert_eq!(smart(&f.engine,id).transform,Affine{m:[0.0001,0.,0.,0.0001,6.,5.]});assert_eq!(result["scale"],0.01);assert_source(&f.engine,id,command,&f.path,&f.bytes);assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);assert_eq!(f.engine.active().unwrap().doc.layer(f.id),before.layer(f.id));continue;}let mut native=twin(&f.engine);let mut pairs=Vec::new();let(id,result)=differential(&mut f.engine,&mut native,command,request,&mut pairs);assert_eq!(smart(&f.engine,id).transform,Affine{m:[expected.0,0.,0.,expected.0,expected.1,expected.2]});assert_eq!(result["scale"],expected.0*100.);if expected.0==1.{pixels(&f.engine,id,Rect::from_xywh(expected.1 as i32,expected.2 as i32,2,2),&[255,0,0,255].repeat(4));}else if expected.0==2.{enlarged_red(&f.engine,id,expected.1 as i32,expected.2 as i32);}}
        for (settings,expected,rect)in [(json!({}),(0.6,0.,2.),Rect::new(0,2,12,8)),(json!({"fit":false}),(1.,-4.,0.),Rect::new(-4,0,16,10)),(json!({"fit":true,"scale":200}),(2.,-14.,-5.),Rect::new(-14,-5,26,15))]{let mut f=fixture(16,"png");f.bytes=png(20,10,[0,255,0,255].repeat(200));std::fs::write(&f.path,&f.bytes).unwrap();let mut request=params(&f);request.as_object_mut().unwrap().extend(settings.as_object().unwrap().clone());assert_eq!(geometry((12,10),(20,10),&request).unwrap(),expected);let mut native=twin(&f.engine);let mut pairs=Vec::new();let(id,_)=differential(&mut f.engine,&mut native,command,request,&mut pairs);if expected.0==1.{pixels(&f.engine,id,rect,&[0,255,0,255].repeat(200));}else{solid_bounds_and_interior(&f.engine,id,rect,[0.,1.,0.,1.]);}}
    }
}

#[test]
fn place_input_pure_geometry_rejects_huge_sources_results_and_i32_extents_before_flattening(){
    assert_eq!(geometry((12,10),(16384,16384),&json!({})).unwrap(),(10./16384.,1.,0.));assert!(geometry((12,10),(16385,16384),&json!({})).unwrap_err().contains("source"));assert!(geometry((12,10),(0,2),&json!({})).is_err());assert!(geometry((12,10),(2,0),&json!({})).is_err());assert!(geometry((12,10),(u32::MAX,u32::MAX),&json!({})).is_err());assert_eq!(geometry((12,10),(2,2),&json!({"scale":819200,"fit":false})).unwrap().0,8192.);assert!(geometry((12,10),(2,2),&json!({"scale":819201})).is_err());assert_eq!(geometry((12,10),(2,2),&json!({"center":[2147483646,5]})).unwrap(),(1.,2147483645.,4.));assert!(geometry((12,10),(2,2),&json!({"center":[2147483647,5]})).is_err());assert_eq!(geometry((12,10),(2,2),&json!({"center":[-2147483647,5]})).unwrap(),(1.,-2147483648.,4.));assert!(geometry((12,10),(2,2),&json!({"center":[-2147483648i64,5]})).is_err());assert!(geometry((12,10),(2,2),&json!({"center":[1e300,0]})).is_err());
}

#[test]
fn place_input_group_nested_no_active_channels_mask_and_stale_slices_match_native_insert_order(){
    for command in [EMBEDDED,LINKED]{for context in ["group","nested","noActive","alpha","quickMask","mask","staleSlices"]{let mut f=fixture(16,"png");match context{"group"=>{f.engine.select_layer(f.group).unwrap();},"nested"=>{f.engine.select_layer(f.nested).unwrap();},"noActive"=>f.engine.active_mut().unwrap().active_layer=None,"quickMask"=>f.engine.active_mut().unwrap().channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Composite,"mask"=>{f.engine.execute("view.layerMask",json!({"mode":"gray"})).unwrap();},"staleSlices"=>{f.engine.edit("Stale slice",|doc,_|{doc.slices.list[0].rect=Rect::from_xywh(99,99,1,1);doc.slices.list.push(Slice{id:2,origin:SliceOrigin::Layer,layer:Some(LayerId(u64::MAX)),..Default::default()});Ok(())}).unwrap();},_=>{}}let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut pairs=Vec::new();let mut request=params(&f);request["target"]=json!("pixels");let(id,_)=differential(&mut f.engine,&mut native,command,request,&mut pairs);pixels(&f.engine,id,Rect::new(5,4,7,6),&rgba());let doc=&f.engine.active().unwrap().doc;assert_eq!(doc.selection,before.selection);assert_eq!(doc.channels,before.channels);assert_eq!(doc.quick_mask,before.quick_mask);assert_eq!(doc.layer(f.id),before.layer(f.id));assert_eq!(doc.slices.list.len(),1);if context=="nested"{assert_eq!(doc.layer(f.group).unwrap().children().unwrap().iter().map(|layer|layer.id).collect::<Vec<_>>(),vec![f.nested,id]);}else if context=="group"||context=="noActive"{assert_eq!(doc.layers.last().unwrap().id,id);}}}
}

#[test]
fn place_input_reads_disk_once_before_donor_removal_and_ignores_colliding_linked_metadata(){
    use photocraft_io::linked::{encode_linked_file,LinkedFile};for command in [EMBEDDED,LINKED]{let mut f=fixture(16,"png");let block=encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"must-not-substitute.png".into(),bytes:png(2,2,[0,0,0,255].repeat(4))});f.engine.edit("Conflicting linked metadata",|doc,_|{doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(block)));Ok(())}).unwrap();let request=params(&f);let path=f.path.to_string_lossy().into_owned();let mut reads=0;let result=run_with(&mut f.engine,command,&request,&path,|actual|{reads+=1;assert_eq!(actual,f.path.as_path());let bytes=super::super::input::read_source_file(actual)?;std::fs::remove_file(actual).unwrap();Ok(bytes)}).unwrap();let id=LayerId(result["layer"].as_u64().unwrap());assert_eq!(reads,1);assert!(!f.path.exists());assert_source(&f.engine,id,command,&f.path,&f.bytes);pixels(&f.engine,id,Rect::new(5,4,7,6),&rgba());}
}

#[test]
fn place_input_missing_corrupt_oversize_directory_growth_reader_panic_and_huge_geometry_leave_owner_unchanged(){
    for command in [EMBEDDED,LINKED]{for failure in ["missing","corrupt","oversize","directory","growing","panic","scale","position"]{let mut f=fixture(16,"png");let mut request=params(&f);match failure{"missing"=>std::fs::remove_file(&f.path).unwrap(),"corrupt"=>std::fs::write(&f.path,b"not an image").unwrap(),"oversize"=>std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::MAX_INPUT_BYTES+1).unwrap(),"directory"=>{std::fs::remove_file(&f.path).unwrap();std::fs::create_dir(&f.path).unwrap();},"scale"=>request["scale"]=json!(1e100),"position"=>request["center"]=json!([1e100,0]),_=>{}}let before=twin(&f.engine);let path=f.path.to_string_lossy().into_owned();let error=match failure{"panic"=>run_with(&mut f.engine,command,&request,&path,|_|panic!("injected placement reader panic")).unwrap_err(),"growing"=>{struct Growing{read:usize,max:usize}impl Read for Growing{fn read(&mut self,out:&mut[u8])->std::io::Result<usize>{self.max=self.max.max(out.len());out.fill(0x7a);self.read+=out.len();Ok(out.len())}}let mut reader=Growing{read:0,max:0};let error=run_with(&mut f.engine,command,&request,&path,|_|super::super::smart::replay_read_with_limit(&mut reader,32)).unwrap_err();assert_eq!(reader.read,33);assert!(reader.max<=64*1024);error},_=>host(&mut f.engine,command,request.clone()).unwrap_err()};unchanged(&f.engine,&before);match failure{"oversize"|"growing"=>assert!(error.contains("512MB")),"directory"=>assert!(error.contains("not a regular file")),"panic"=>{assert!(error.contains(command));assert!(error.contains("internal error"));},"scale"|"position"=>assert!(error.contains("editing limit")),_=>{let mut native=twin(&before);assert_eq!(error,native.execute(command,request).unwrap_err().to_string());}}}}
}

#[test]
fn place_input_mixed_command_coalescing_preserves_first_label_older_fade_and_native_undo_targets(){
    for first in [EMBEDDED,LINKED]{let mut f=fixture(32,"png");let before=f.engine.active().unwrap().doc.clone();let fade=f.engine.edit_state.fade.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let mut pairs=Vec::new();for command in [first,if first==EMBEDDED{LINKED}else{EMBEDDED},first]{let mut request=params(&f);request["coalesce"]=json!("placed-images");differential(&mut f.engine,&mut native,command,request,&mut pairs);assert_eq!(f.engine.edit_state.fade,fade);}assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.active().unwrap().history.undo_label(),Some(if first==EMBEDDED{"Place Embedded"}else{"Place Linked"}));assert_eq!(f.engine.journal.len(),journal+3);let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert_eq!(f.engine.active().unwrap().doc,after);}
}

#[test]
fn place_input_pending_owner_preset_store_flushes_only_after_successful_prepared_placement(){
    use photocraft_engine::preset_store::{open,MemBackend};for command in [EMBEDDED,LINKED]{let mut f=fixture(16,"png");let mut native=twin(&f.engine);let actual=MemBackend::default();let expected=MemBackend::default();f.engine.attach_preset_store(open(Box::new(actual.clone())));native.attach_preset_store(open(Box::new(expected.clone())));for owner in [&mut f.engine,&mut native]{let mut preset=owner.tools.presets[0].clone();preset.name="Pending placement brush".into();preset.group="Placement owner".into();preset.builtin=false;owner.tools.presets.push(preset);owner.brush_presets_changed();}let files=actual.files.lock().unwrap().clone();let before=twin(&f.engine);let request=params(&f);let path=f.path.to_string_lossy().into_owned();assert!(run_with(&mut f.engine,command,&request,&path,|_|Err("independent read failure".into())).is_err());unchanged(&f.engine,&before);assert_eq!(*actual.files.lock().unwrap(),files);let mut pairs=Vec::new();differential(&mut f.engine,&mut native,command,request,&mut pairs);let after=actual.files.lock().unwrap().clone();assert_ne!(after,files);assert_eq!(after,*expected.files.lock().unwrap());assert!(open(Box::new(actual)).presets.iter().any(|preset|preset.name=="Pending placement brush"));}
}

#[test]
fn place_input_actual_immutable_host_reopen_with_redo_retains_source_transform_cache_and_original(){
    for command in [EMBEDDED,LINKED]{let mut f=fixture(16,"psb");f.engine.active_mut().unwrap().channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Color(1);let before=f.engine.active().unwrap().doc.clone();let labels=f.engine.active().unwrap().history.entries();let request=params(&f);let id=LayerId(host(&mut f.engine,command,request).unwrap()["layer"].as_u64().unwrap());let after=f.engine.active().unwrap().doc.clone();let mut session=super::super::PhotoSession{engine:f.engine,color_settings:None,version:String::new(),original_path:None,writer:Default::default()};let photo=ulid::Ulid::new().to_string();super::super::publish(&f.directory.0,&photo,&mut session).unwrap();let saved=f.directory.0.join(format!("{}.pcraft",session.version));let bytes=super::super::bundle::portable_bytes(&saved,super::super::MAX_INPUT_BYTES as usize).unwrap();std::fs::remove_file(&f.path).unwrap();session.engine.execute("edit.undo",json!({})).unwrap();super::super::publish(&f.directory.0,&photo,&mut session).unwrap();super::super::save_view(&f.directory.0,&session).unwrap();let mut reopened=super::super::restore_with_settings(&f.directory.0,&session.version,None,false).unwrap();let state=reopened.engine.active().unwrap();assert_eq!(state.doc,before);assert_eq!(state.history.entries(),labels);assert!(state.history.can_redo());assert_eq!(state.channel_view.target,photocraft_engine::channel_cmds::ChannelTarget::Color(1));reopened.engine.execute("edit.redo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,after);assert_source(&reopened.engine,id,command,&f.path,&f.bytes);pixels(&reopened.engine,id,Rect::new(5,4,7,6),&rgba());reopened.engine.execute("edit.undo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,before);assert_eq!(bytes,super::super::bundle::portable_bytes(&saved,super::super::MAX_INPUT_BYTES as usize).unwrap());}
}

#[test]
fn place_input_native_path_parameter_no_document_and_active_job_errors_precede_reads(){
    for command in [EMBEDDED,LINKED]{for request in [Value::Null,json!({}),json!({"path":""}),json!({"path":17}),json!([]),json!(42),json!("invalid")]{let mut f=fixture(8,"png");let before=twin(&f.engine);let mut native=twin(&f.engine);assert_eq!(host(&mut f.engine,command,request.clone()).unwrap_err(),native.execute(command,request).unwrap_err().to_string());unchanged(&f.engine,&before);}let mut empty=Session::new();assert_eq!(host(&mut empty,command,json!({})).unwrap_err(),empty.execute(command,json!({})).unwrap_err().to_string());let mut f=fixture(8,"png");let release=Arc::new(AtomicBool::new(false));let worker=release.clone();struct Release(Arc<AtomicBool>);impl Drop for Release{fn drop(&mut self){self.0.store(true,Ordering::Relaxed);}}let _release=Release(release.clone());let started=f.engine.start_job("place-test",json!({}),"Retained placement job",true,move|context|{while !worker.load(Ordering::Relaxed){context.check()?;std::thread::yield_now();}Ok(())},|_,_|Ok(Value::Null)).unwrap();let photocraft_engine::jobs::Started::Job(job)=started else{panic!("Expected native job")};let before=twin(&f.engine);std::fs::remove_file(&f.path).unwrap();let request=params(&f);let error=host(&mut f.engine,command,request.clone()).unwrap_err();assert_eq!(error,f.engine.execute(command,request).unwrap_err().to_string());assert!(error.contains("Retained placement job"));unchanged(&f.engine,&before);release.store(true,Ordering::Relaxed);f.engine.wait_job(job).unwrap();}
}

#[test]
fn place_input_forced_stream_matches_safe_native_bicubic_raw_channels_alpha_depths_and_subpixel_scales(){
    for sample in SampleType::ALL{for mode in [ColorMode::Rgb,ColorMode::Grayscale,ColorMode::Cmyk]{for alpha in [false,true]{let format=PixelFormat{mode,sample,alpha};let channels=format.channels();for origin in [(0,0),(-2,-1)]{let mut source=photocraft_raster::Surface::new(format);let rect=Rect::from_xywh(origin.0,origin.1,5,4);let mut data=Vec::new();for index in 0..20{for channel in 0..channels{data.push(if alpha&&channel==channels-1{[0.,0.25,0.7,1.][index%4]}else{((index*13+channel*7)%31)as f32/30.});}}source.write_region(rect,&data);source.prune();let before=source.clone();for scale in [0.5,0.73,1.5,2.,0.01]{let native=photocraft_algo::resample::resize_surface(&source,scale,scale,photocraft_algo::resample::Resample::Bicubic);let streamed=super::resample::streamed(&source,scale).unwrap();let automatic=super::resample::resize(&source,scale).unwrap();assert_eq!(streamed,native,"forced {format:?}/{origin:?}/{scale}");assert_eq!(automatic,native,"safe automatic {format:?}/{origin:?}/{scale}");assert_eq!(source,before);}}}}}
    let mut nonzero=photocraft_raster::Surface::with_default(PixelFormat::RGBA32F,&[0.2,0.3,0.4,1.]);nonzero.fill_rect(Rect::from_xywh(0,0,3,2),&[0.6,0.1,0.8,0.5]);assert!(super::resample::streamed(&nonzero,0.5).is_err());assert_eq!(super::resample::resize(&nonzero,0.5).unwrap(),photocraft_algo::resample::resize_surface(&nonzero,0.5,0.5,photocraft_algo::resample::Resample::Bicubic));
}

#[test]
fn place_input_extreme_scale_streamed_f32_alpha_matches_independent_literal_without_native_halo_allocation(){
    // Complete Keys weights sum to 10000. Source centres contribute .5625687493748125 and .5627062443699375.
    const EXPECTED_ALPHA:f32=1.266243811547247e-8;
    for command in [EMBEDDED,LINKED]{for scale in [0.,-5.,0.000001]{let mut f=fixture(32,"png");let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut request=params(&f);request["scale"]=json!(scale);let result=host(&mut f.engine,command,request).unwrap();let id=LayerId(result["layer"].as_u64().unwrap());assert_eq!(smart(&f.engine,id).transform,Affine{m:[0.0001,0.,0.,0.0001,6.,5.]});assert_eq!(result,json!({"layer":id.0,"scale":0.01,"bounds":[6.,5.,6.0002,5.0002]}));assert_source(&f.engine,id,command,&f.path,&f.bytes);let cache=smart(&f.engine,id).cache.as_ref().unwrap();for y in 0..10{for x in 0..12{let actual=cache.pixel(x,y);assert_eq!(&actual[..3],&[0.;3]);if(x,y)==(6,5){assert!(actual[3]>0.);assert!((actual[3]-EXPECTED_ALPHA).abs()<=5e-15,"tiny alpha {} != {}",actual[3],EXPECTED_ALPHA);}else{assert_eq!(actual[3],0.);}}}assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();assert_eq!(f.engine.active().unwrap().doc,after);assert_eq!(std::fs::read(&f.path).unwrap(),f.bytes);}}
    assert_eq!(geometry((1,1),(20000,1),&json!({})).unwrap(),(0.00005,0.,0.));
    for command in [EMBEDDED,LINKED]{let mut f=fixture(32,"png");f.engine.execute("file.new",json!({"width":1,"height":1,"depth":32})).unwrap();f.bytes=png(20000,1,[255,0,0,255].repeat(20000));std::fs::write(&f.path,&f.bytes).unwrap();let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let request=params(&f);let result=host(&mut f.engine,command,request).unwrap();let id=LayerId(result["layer"].as_u64().unwrap());assert_eq!(smart(&f.engine,id).transform,Affine{m:[0.00005,0.,0.,0.00005,0.,0.]});assert_eq!(result,json!({"layer":id.0,"scale":0.005,"bounds":[0.,0.,1.,0.00005]}));assert_source(&f.engine,id,command,&f.path,&f.bytes);let cache=smart(&f.engine,id).cache.as_ref().unwrap();assert_eq!(cache.content_bounds(),Rect::new(0,0,1,1));let pixel=cache.pixel(0,0);assert!(pixel.iter().all(|value|value.is_finite()));assert_eq!(&pixel[..3],&[1.,0.,0.]);assert!(pixel[3]>0.&&pixel[3]<1.);assert_eq!(cache.pixel(1,0),[0.;4]);assert_eq!(cache.pixel(0,1),[0.;4]);assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.journal.len(),journal+1);let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();assert_eq!(f.engine.active().unwrap().doc,after);assert_eq!(std::fs::read(&f.path).unwrap(),f.bytes);}
}

#[test]
fn place_input_names_pasted_sources_from_the_request(){
    let mut f=fixture(8,"png");
    let result=host(&mut f.engine,EMBEDDED,json!({"path":f.path.to_string_lossy(),"name":"Pasted Image.png"})).unwrap();
    let id=LayerId(result["layer"].as_u64().unwrap() as _);
    assert_eq!(f.engine.active().unwrap().doc.layer(id).unwrap().name,"Pasted Image");
    let SmartSource::Embedded{file_name,..}=&smart(&f.engine,id).source else{panic!("Not embedded")};
    assert_eq!(file_name,"Pasted Image.png");
}
